    elif 'TESSARO STUDIOS' in desc:
        if d.startswith('2024'):
            add(r, 'prior_year', 'n/a', 'Invoice 1041 payment received 2024-12-27; cash method -> 2024 return. Tessaro 2025 1099-NEC ($9,400.00) excludes it')
        else:
            add(r, 'business_income', '1', 'Direct ACH from Tessaro Studios; the four 2025 ACH credits total $9,400.00 = Tessaro 2025 1099-NEC; not part of PayHub 1099-K (no card/TPSO)')
    elif 'LARKSPUR' in desc:
        add(r, 'other_schedule', 'n/a', 'W-2 wages (Larkspur Interactive), Form 1040 line 1a; not self-employment. 2025 deposits $19,502.80 net; W-2 Box 1 wages $24,800.00')
    elif 'FIGMA' in desc:
        add(r, 'business_expense', '27a', 'Figma software subscription; 12 x $45.00 = $540.00 -> line 27a')
    elif 'ADOBE' in desc:
        add(r, 'business_expense', '27a', 'Adobe Creative Cloud; 12 x $59.99 = $719.88 -> line 27a')
    elif 'NETFLIX' in desc:
        add(r, 'personal', '', 'Personal streaming - IRC 262(a); not deductible')
    elif 'ORANGETHEORY' in desc:
        add(r, 'personal', '', 'Gym membership - IRC 262(a); not deductible')
    elif 'H-E-B' in desc:
        if d.startswith('2024'):
            add(r, 'prior_year', '', 'Groceries paid 2024-12-30; personal (IRC 262) and belongs to 2024')
        else:
            add(r, 'personal', '', 'Groceries/debit-card purchases - personal IRC 262(a); 2025 total $2,102.95')
    elif desc.startswith('ZELLE'):
        add(r, 'personal', '', 'Rent paid to M. Okafor 12 x $1,650.00 = $19,800.00; personal. Home-office question pending (no exclusive business use documented)')
    elif 'T-MOBILE' in desc:
        add(r, 'business_expense', '25', 'Mobile phone 12 x $85.00 = $1,020.00; business-use % requested (QUESTIONS.md Q4) - $0 deducted pending')
    elif 'SPECTRUM' in desc:
        add(r, 'business_expense', '25', 'Home internet 12 x $70.00 = $840.00; business-use % requested (QUESTIONS.md Q4) - $0 deducted pending')
    elif 'CAPITAL FACTORY' in desc:
        add(r, 'business_expense', '20b', 'Coworking membership 8 x $350.00 (May-Dec) = $2,800.00 -> line 20b')
    elif 'BLUE CROSS' in desc:
        add(r, 'other_schedule', '', 'Self-employed health insurance premium 8 x $380.00 = $3,040.00 -> Schedule 1 line 17; NOT Schedule C line 15 (per 2025 Sch C instructions)')
    elif 'HISCOX' in desc:
        add(r, 'business_expense', '15', 'Professional liability insurance (business, other than health) -> line 15')
    elif 'IRS USATAXPYMT' in desc:
        qtr = 'Q1' if 'Q1' in desc else ('Q2' if 'Q2' in desc else 'Q3')
        add(r, 'tax_payment', '', f'2025 federal estimated tax ({qtr}) -> Form 1040 line 26; visible total $6,500.00 (Q4 2025 not in export)')
    elif desc.startswith('SOUTHWEST AIR 118'):
        add(r, 'personal', '', 'June Denver flight $389.00; no business purpose documented (wedding trip - gift Venmo $200.00 on 6/14); Pub 463 personal travel; confirm')
    elif desc.startswith('SOUTHWEST AIR 526'):
        add(r, 'business_expense', '24a', 'Oct airfare AUS-SFO for DesignWeek SF -> line 24a')
    elif 'HOTEL ZEPHYR' in desc:
        add(r, 'business_expense', '24a', 'Oct SF lodging -> line 24a')
    elif 'DESIGNWEEK' in desc:
        add(r, 'business_expense', '27a', 'Conference registration -> line 27a (professional development)')
    elif 'MARINA DELI' in desc:
        add(r, 'business_expense', '24b', 'Meal during Oct SF business trip; deductible 50% = $32.00 on line 24b')
    elif 'TARTINE' in desc:
        add(r, 'business_expense', '24b', 'Meal during Oct SF business trip; deduct 50% = $63.00; business purpose to confirm (QUESTIONS.md Q5)')
    elif 'APPLE.COM' in desc:
        add(r, 'business_expense', '27a', 'MacBook Pro 14 $2,149.00; de minimis safe harbor election (<= $2,500/item) -> line 27a; business-use assumed 100% (confirm, Q6)')
    elif desc.startswith('VENMO'):
        add(r, 'personal', '', 'Wedding gift - personal IRC 262(a)')
    else:
        raise SystemExit('UNCLASSIFIED: ' + r['date'] + ' ' + desc)

assert used[0] == len(rows), (used[0], len(rows))
# sum check
print('rows written:', len(out), 'of', len(rows))
cls_counts = {}
for o in out: cls_counts[o['classification']] = cls_counts.get(o['classification'], 0) + 1
print('classifications:', cls_counts)

with open('deliverable/classification.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=['date','description','amount','classification','schedule_c_line','note'])
    w.writeheader()
    for o in out: w.writerow(o)

# quick sums by class for md
from decimal import Decimal as D
s = {}
for o in out:
    k = o['classification']
    s[k] = s.get(k, D('0')) + D(o['amount'])
for k, v in s.items(): print(k, v)
EOF

