{"command": "cd /work/workspace && python3 - <<'EOF'
import csv
from decimal import Decimal
rows = list(csv.DictReader(open('deliverable/classification.csv')))
from collections import defaultdict
groups = defaultdict(list)
for r in rows:
    if r['classification'] in ('personal','other_schedule','prior_year','tax_payment','transfer'):
        groups[r['classification']].append(r)
for k in sorted(groups):
    tot = sum(Decimal(r['amount']) for r in groups[k])
    print(f"\n== {k}  total {tot}  n={len(groups[k])}")
    for r in groups[k]: print('  ', r['date'], r['amount'], r['description'][:55], '|', (r.get('note') or '')[:48])
EOF"}

